### Creates a default (main) route table and default (main) NACL
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  tags = merge(
    var.default_tags,
    {
      Name = "terraform-vpc-${var.stack_name}"
    },
  )
}

resource "aws_internet_gateway" "internet-gw" {
  vpc_id = aws_vpc.main.id
  tags = merge(
    var.default_tags,
    {
      Name = "terraform-vpc-igw-${var.stack_name}"
    },
  )
}

resource "aws_route_table" "this" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet-gw.id
  }
  tags = merge(
    var.default_tags,
    {
      Name = "custom-routetable-${var.stack_name}"
    },
  )
}

resource "aws_subnet" "public_subnet" {
  # If you do not explictly state which route table the subnet is associated with,
  # it will be associated with the default route table.
  count                   = length(var.list_of_azs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.list_of_cidr_range[count.index]
  availability_zone       = var.list_of_azs[count.index]
  map_public_ip_on_launch = true
  tags = merge(
    var.default_tags,
    {
      Name = format("terraform_public_subnet_%s", (count.index + 1))
    },
  )
}

resource "aws_route_table_association" "public" {
  count          = length(var.list_of_azs)
  subnet_id      = aws_subnet.public_subnet[count.index].id
  route_table_id = aws_route_table.this.id
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "example" {
  name               = "K8s-cluster-cloud"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy_attachment" "example-AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.example.name
}

#get vpc data
data "aws_vpc" "default" {
  default = true
}
#get public subnets for cluster
data "aws_subnets" "public" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}
#cluster provision
resource "aws_eks_cluster" "example" {
  name     = "EKS_CLOUD"
  role_arn = aws_iam_role.example.arn

  vpc_config {
    subnet_ids = data.aws_subnets.public.ids
  }

  # Ensure that IAM Role permissions are created before and deleted after EKS Cluster handling.
  # Otherwise, EKS will not be able to properly delete EKS managed EC2 infrastructure such as Security Groups.
  depends_on = [
    aws_iam_role_policy_attachment.example-AmazonEKSClusterPolicy,
  ]
}

resource "aws_iam_role" "example1" {
  name = "eks-node-group-cloud"

  assume_role_policy = jsonencode({
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
    Version = "2012-10-17"
  })
}

resource "aws_iam_role_policy_attachment" "example-AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.example1.name
}

resource "aws_iam_role_policy_attachment" "example-AmazonEKS_CNI_Policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.example1.name
}

resource "aws_iam_role_policy_attachment" "example-AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.example1.name
}

#create node group
resource "aws_eks_node_group" "example" {
  cluster_name    = aws_eks_cluster.example.name
  node_group_name = "EKS_CLUSTER"
  node_role_arn   = aws_iam_role.example1.arn
  subnet_ids      = data.aws_subnets.public.ids

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }
  instance_types = ["t2.medium"]

  # Ensure that IAM Role permissions are created before and deleted after EKS Node Group handling.
  # Otherwise, EKS will not be able to properly delete EC2 Instances and Elastic Network Interfaces.
  depends_on = [
    aws_iam_role_policy_attachment.example-AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.example-AmazonEKS_CNI_Policy,
    aws_iam_role_policy_attachment.example-AmazonEC2ContainerRegistryReadOnly,
  ]
}

# Provider Configuration
provider "vault" {
  address = var.vault_address
}

provider "aws" {
  region = var.aws_region
}

# Generate a Key Pair
resource "tls_private_key" "ec2_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

# Store the Private Key in Vault
resource "vault_generic_secret" "pem_file" {
  path      = var.pem_path
  data_json = jsonencode({
    private_key = tls_private_key.ec2_key.private_key_pem
  })
}

# Retrieve the Private Key from Vault (if needed for other uses)
data "vault_generic_secret" "retrieved_pem" {
  path = var.pem_path
}

# Create the Key Pair in AWS using the Public Key
resource "aws_key_pair" "ec2_key_pair" {
  key_name   = var.key_pair_name
  public_key = tls_private_key.ec2_key.public_key_openssh
}

# AWS EC2 Instance
resource "aws_instance" "example" {
  ami           = "ami-12345678" # Replace with a valid AMI
  instance_type = "t2.micro"

  key_name = aws_key_pair.ec2_key_pair.key_name

  tags = {
    Name = "SecureInstance"
  }
}

resource "aws_lb" "discourse" {
  name                             = var.alb_name
  enable_cross_zone_load_balancing = true
  internal                         = false
  load_balancer_type               = "application"
  security_groups                  = [ aws_security_group.alb.id ]
  subnets                          = var.subnet_ids
  tags                             = local.alb_tags
}

resource "aws_lb_listener" "discourse_80" {
  load_balancer_arn  = aws_lb.discourse.arn
  port               = "80"
  protocol           = "HTTP"

  default_action {
    type            = "redirect"

    redirect {
      port          = "443"
      protocol      = "HTTPS"
      status_code   = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "discourse" {
  load_balancer_arn  = aws_lb.discourse.arn
  port               = "443"
  protocol           = "HTTPS"
  ssl_policy         = "ELBSecurityPolicy-2016-08"
  certificate_arn    = var.alb_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.discourse.arn
  }
}

resource "aws_lb_target_group" "discourse" {
  name        = var.alb_tg_name
  port        = "3000"
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  target_type = "ip"

  health_check {
    interval            = 30
    path                = "/srv/status"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = "5"
    healthy_threshold   = "2"
    unhealthy_threshold = "2"
    matcher             = "200"
  }

  tags = local.alb_tags
}

# CREATE OPENVPN ACCESS SERVER INSTANCE
resource "aws_instance" "openvpn" {
  ami                  = var.openvpn_ami
  instance_type        = var.openvpn_instance_size
  key_name             = var.openvpn_key_name
  subnet_id            = var.openvpn_subnet_id
  iam_instance_profile = aws_iam_instance_profile.openvpn.name
  user_data            = data.template_file.user_data.rendered

  vpc_security_group_ids = [aws_security_group.openvpn.id]

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name        = "OpenVPN Access Server"
    Environment = lower(terraform.workspace) #
    Stack       = lower(var.stack_name)
  }
}

# USER DATA TEMPLATE TO PRE-CONFIGURE THE OPENVPN ACCESS SERVER
data "template_file" "user_data" {
  template = file("${path.module}/user_data.tpl")

  vars = {
    public_hostname = var.openvpn_public_hostname
    admin_user      = var.openvpn_admin_user
    admin_pswd      = var.openvpn_admin_pswd
    license_key     = var.openvpn_license
    reroute_gw      = var.openvpn_reroute_gw
    reroute_dns     = var.openvpn_reroute_dns
  }
}

variable "region" {
  type = string
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "ltthw_aws_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "ltthw_aws_vpc_subnet" {
  vpc_id     = aws_vpc.ltthw_aws_vpc.id
  cidr_block = aws_vpc.ltthw_aws_vpc.cidr_block
}

resource "local_file" "ltthw_local_file" {
  content  = "I am Sumit Das - Dark Lord of DevOps"
  filename = "${path.module}/ltthw_local_file.txt"
  depends_on = [
    aws_vpc.ltthw_aws_vpc
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.16"
    }
  }

  required_version = ">= 1.2.0"
}

data "aws_ami" "ubuntu" {
  most_recent = true

  filter {
    name   = "name"
    #arm64
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-arm64-server-*"]
    #x86_64
    #values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
  owners = ["099720109477"]
}

resource "random_string" "agent_token" {
  length  = 24
  special = false
}

resource "random_string" "k3s_edge_id" {
  length  = 24
  special = false
}

resource "aws_iam_instance_profile" "instance_profile" {
  name  = "${var.deployment_name}-InstanceProfile"
  role  = var.iam_role_name
  count = var.iam_role_name == null ? 0 : 1
}

data "cloudinit_config" "userData" {
  part {
    content      = <<EOF
#cloud-config
---
hostname: "${var.deployment_name}"
EOF
    content_type = "text/cloud-config"
  }

  part {
    content      = <<EOF
#!/bin/bash
echo "----- Installing k3s"
echo K3S_KUBECONFIG_MODE=${var.kubeconfig_mode} K3S_TOKEN=${random_string.agent_token.result} email=${var.letsencrypt_email} > /tmp/variables
curl -sfL https://get.k3s.io | K3S_KUBECONFIG_MODE=${var.kubeconfig_mode} K3S_TOKEN=${random_string.agent_token.result} sh - 
echo "----- updating ubuntu"
apt-get update -y && apt-get upgrade -y && apt-get install awscli git -y
echo "----- Adding helm"
curl https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3 | bash
echo "export KUBECONFIG=/etc/rancher/k3s/k3s.yaml" >> /home/ubuntu/.profile
echo "export KUBECONFIG=/etc/rancher/k3s/k3s.yaml" >> /home/ubuntu/.bashrc
export ADVERTISE_IP=$(curl http://169.254.169.254/latest/meta-data/public-ipv4)
export PUBLIC_HOSTNAME=$(curl http://169.254.169.254/latest/meta-data/public-hostname | cut -d '.' -f 1 | sed 's/^ec2-//')
export LOCAL_IP=$(curl http://169.254.169.254/latest/meta-data/local-ipv4)
echo "----- Wating for k3s to start"
until [ -f /etc/rancher/k3s/k3s.yaml ]
do
     sleep 5
done
echo "----- Adding smarter-cloud to k3s"
sudo su - ubuntu bash -c "helm repo add smarter https://smarter-project.github.io/documentation;helm install my-smartercloud smarter/smarter-cloud --set email=${var.letsencrypt_email} --set host=grafana --set domain=$PUBLIC_HOSTNAME.sslip.io --set prometheus.grafana.adminPassword=${random_string.k3s_edge_id.result} --wait"
echo "----- Checking if TLS certificate was generated"
until [ ! -z "$(kubectl get secret/my-smartercloud-grafana-tls 2>/dev/null)" ]
do
     echo "Certificate not generated yet, wait 5 seconds and test again"
     sleep 5
done
echo "----- Adding smarter-edge to k3s"
#sudo su - ubuntu bash -c "helm install my-smartercloud-edge smarter/smarter-k3s-edge --set configuration.externalHostIP=$ADVERTISE_IP --set configuration.hostIP=$LOCAL_IP --set configuration.port=6444 --set configuration.portHTTP=80 --set configuration.id='${random_string.k3s_edge_id.result}' --set configuration.smarter_demo_labels=true --set configuration.host=grafana --set configuration.domain=$PUBLIC_HOSTNAME.sslip.io --set configuration.traefik=true --set configuration.certificateID=my-smartercloud-grafana-tls --set configuration.wwwpath=/k3s/ --wait"
sudo su - ubuntu bash -c "helm install my-smartercloud-edge smarter/smarter-k3s-edge --set configuration.externalHostIP=$ADVERTISE_IP --set configuration.hostIP=$LOCAL_IP --set configuration.port=6444 --set configuration.portHTTP=80 --set configuration.id='${random_string.k3s_edge_id.result}' --set configuration.smarter_demo_labels=true --set configuration.host=k3s --set configuration.domain=$PUBLIC_HOSTNAME.sslip.io --set configuration.traefik=true --set configuration.wwwpath=/ --wait"
echo "----- Waiting for k3s.yaml from k3s-edge"
until [ -f /home/ubuntu/k3s.yaml.${random_string.k3s_edge_id.result} ]
do
     #sudo su - ubuntu bash -c "wget --no-check-certificate https://grafana.$PUBLIC_HOSTNAME.sslip.io/k3s/k3s.yaml.${random_string.k3s_edge_id.result}"
     sudo su - ubuntu bash -c "wget --no-check-certificate https://k3s.$PUBLIC_HOSTNAME.sslip.io/k3s.yaml.${random_string.k3s_edge_id.result}"
     if [ -z "$(grep 'kind: Config' /home/ubuntu/k3s.yaml.${random_string.k3s_edge_id.result})" ]
     then
         echo "Received a file but it is not a k3s.yaml file, removing"
         rm /home/ubuntu/k3s.yaml.${random_string.k3s_edge_id.result}
     fi
     sleep 5
done
echo "----- Adding smarter-edge to k3s-edge"
sudo su - ubuntu bash -c "export KUBECONFIG=/home/ubuntu/k3s.yaml.${random_string.k3s_edge_id.result};helm install --create-namespace --namespace smarter my-smartercloud-edge smarter/smarter-edge --wait;helm install --create-namespace --namespace smarter --set global.domain=$(curl http://169.254.169.254/latest/meta-data/public-hostname | cut -d '.' -f 2-) --set smarter-fluent-bit.fluentd.host=$(curl http://169.254.169.254/latest/meta-data/public-hostname | cut -d '.' -f 1) my-smartercloud-demo smarter/smarter-demo --wait"
echo "----- Finished installing"
EOF
    content_type = "text/x-shellscript"
  }

  part {
    content      = var.manifest_bucket_path == "" ? "" : <<EOF
#!/bin/bash
aws s3 sync s3://${var.manifest_bucket_path} /var/lib/rancher/k3s/server/manifests/
EOF
    content_type = "text/x-shellscript"
  }

#  part {
#    content      = <<EOF
##!/bin/bash
#apt-get update && \
#apt-get install ec2-instance-connect -y
#EOF
#    content_type = "text/x-shellscript"
#  }
}

resource "aws_key_pair" "k3s_keypair" {
  key_name   = var.deployment_name
  public_key = var.keypair_content
  count      = 1
}

resource "aws_instance" "k3s_instance" {
  ami                         = var.ami_id == null ? data.aws_ami.ubuntu.id : var.ami_id
  associate_public_ip_address = var.assign_public_ip
  instance_type               = var.instance_type
  key_name                    = aws_key_pair.k3s_keypair[0].key_name
  iam_instance_profile        = var.iam_role_name == null ? null : aws_iam_instance_profile.instance_profile[0].name
  subnet_id                   = var.subnet_id == "" ? "" : var.subnet_id
  vpc_security_group_ids      = var.security_group_ids
  user_data                   = data.cloudinit_config.userData.rendered
  tags = {
      Name = "${var.deployment_name}-k3s"
  }
}

output "instance" {
  value = aws_instance.k3s_instance
}

output "k3s_edge" {
  value = random_string.k3s_edge_id
}

#########################################
# S3 bucket for Wireguard configuration #
#########################################
resource "aws_s3_bucket" "main" {
  bucket        = "${var.s3_bucket_name_prefix}-wireguard-configuration-${var.name_suffix}"
  acl           = "private"
  force_destroy = true

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
      }
    }
  }

  logging {
    target_bucket = aws_s3_bucket.main_logs.id
  }

  policy = <<EOF
{
    "Version": "2008-10-17",
    "Statement": [
        {
            "Effect": "Deny",
            "Principal": "*",
            "Action": "s3:*",
            "Resource": [
                "arn:aws:s3:::${var.s3_bucket_name_prefix}-wireguard-configuration-${var.name_suffix}",
                "arn:aws:s3:::${var.s3_bucket_name_prefix}-wireguard-configuration-${var.name_suffix}/*"
            ],
            "Condition": {
                "Bool": {
                    "aws:SecureTransport": "false"
                }
            }
        }
    ]
}
EOF

  tags = merge(var.tags, { "${local.wg_identification_tag_name}" : local.wg_server_name })
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

#################################################
# Wireguard configuration S3 bucket access logs #
#################################################
resource "aws_s3_bucket" "main_logs" {
  # tfsec:ignore:AWS005
  # tfsec:ignore:AWS077
  bucket        = "${var.s3_bucket_name_prefix}-wireguard-configuration-${var.name_suffix}-logs"
  acl           = "log-delivery-write"
  force_destroy = true

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        // https://docs.aws.amazon.com/AmazonS3/latest/userguide/enable-server-access-logging.html
        // KMS isn't supported for log aggregation buckets
        sse_algorithm = "AES256"
      }
    }
  }

  tags = merge(var.tags, { "${local.wg_identification_tag_name}" : local.wg_server_name })
}

resource "aws_s3_bucket_public_access_block" "main_logs" {
  bucket = aws_s3_bucket.main_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

################################
# S3 bucket for LB access logs #
################################
resource "aws_s3_bucket" "access_logs" {
  # tfsec:ignore:AWS077
  # tfsec:ignore:AWS002
  bucket        = "${var.s3_bucket_name_prefix}-wireguard-access-logs-${var.name_suffix}"
  acl           = "private"
  force_destroy = true

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        // https://docs.aws.amazon.com/AmazonS3/latest/userguide/enable-server-access-logging.html
        // KMS isn't supported for log aggregation buckets
        sse_algorithm = "AES256"
      }
    }
  }

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::${data.aws_elb_service_account.main.id}:root"
      },
      "Action": "s3:PutObject",
      "Resource": "arn:aws:s3:::${var.s3_bucket_name_prefix}-wireguard-access-logs-${var.name_suffix}/lb-main/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
    },
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "delivery.logs.amazonaws.com"
      },
      "Action": "s3:PutObject",
      "Resource": "arn:aws:s3:::${var.s3_bucket_name_prefix}-wireguard-access-logs-${var.name_suffix}/lb-main/AWSLogs/${data.aws_caller_identity.current.account_id}/*",
      "Condition": {
        "StringEquals": {
          "s3:x-amz-acl": "bucket-owner-full-control"
        }
      }
    },
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "delivery.logs.amazonaws.com"
      },
      "Action": "s3:GetBucketAcl",
      "Resource": "arn:aws:s3:::${var.s3_bucket_name_prefix}-wireguard-access-logs-${var.name_suffix}"
    }
  ]
}
EOF

  lifecycle_rule {
    enabled = true

    transition {
      days          = 30
      storage_class = "ONEZONE_IA"
    }

    transition {
      days          = 90
      storage_class = "GLACIER"
    }

    expiration {
      days = 120
    }
  }

  tags = merge(var.tags, { "${local.wg_identification_tag_name}" : local.wg_server_name })
}

#############################################################
# Manages S3 bucket-level Public Access Block configuration #
#############################################################
resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

############################################################
# Push message to SQS when Wireguard configuration changed #
############################################################
resource "aws_s3_bucket_notification" "main" {
  bucket = aws_s3_bucket.main.id

  queue {
    queue_arn     = aws_sqs_queue.main.arn
    events        = ["s3:ObjectCreated:*"]
    filter_suffix = ".conf"
  }

  depends_on = [aws_sqs_queue_policy.main]
}

################################################
# Upload Wireguard configuration from template #
################################################
resource "aws_s3_bucket_object" "main" {
  bucket  = aws_s3_bucket.main.id
  key     = "${local.wg_interface_name}.conf"
  content = local.wg_server_config
  tags    = var.tags
}

locals {
  vpc_id = data.aws_subnet.subnet.vpc_id

  iops_by_type = {
    root = {
      "gp3" : max(3000, var.instance_config["root_volume_iops"]),
      "io1" : max(100, var.instance_config["root_volume_iops"]),
      "io2" : max(100, var.instance_config["root_volume_iops"]),
    }
  }
  throughput_by_type = {
    root = {
      "gp3" : 125,
    }
  }
  vpc_security_group_ids = var.enable_extra_sg ? concat([aws_security_group.worker_group[0].id], var.security_group_ids) : var.security_group_ids
  asg_max_size           = var.instance_config["max_count"] != null ? var.instance_config["max_count"] : (var.instance_config["count"] == 0 ? 3 : (var.instance_config["count"] * 3))
}

data "aws_subnet" "subnet" {
  id = var.subnet_ids[0]
}

resource "aws_autoscaling_group" "worker" {
  name_prefix         = "${var.name}-worker-${var.instance_config["name"]}-"
  desired_capacity    = var.instance_config["count"]
  max_size            = local.asg_max_size
  min_size            = var.instance_config["count"]
  vpc_zone_identifier = var.subnet_ids

  default_cooldown          = var.instance_config["default_cooldown"]
  health_check_grace_period = var.instance_config["health_check_grace_period"]

  suspended_processes = var.instance_config["suspended_processes"]

  dynamic "instance_refresh" {
    for_each = var.instance_config["instance_refresh"] ? [1] : []
    content {
      strategy = "Rolling"
      preferences {
        instance_warmup        = var.instance_config["instance_warmup"]
        min_healthy_percentage = var.instance_config["min_healthy_percentage"]
      }
    }
  }

  dynamic "launch_template" {
    for_each = var.asg_warm_pool["enabled"] ? [1] : []

    content {
      id      = aws_launch_template.worker.id
      version = aws_launch_template.worker.latest_version
    }
  }

  dynamic "warm_pool" {
    for_each = var.asg_warm_pool["enabled"] ? [1] : []

    content {
      pool_state                  = "Stopped"
      min_size                    = var.asg_warm_pool["min_size"]
      max_group_prepared_capacity = var.asg_warm_pool["max_group_prepared_capacity"]

      instance_reuse_policy {
        reuse_on_scale_in = var.asg_warm_pool["reuse_on_scale_in"]
      }
    }
  }

  capacity_rebalance = var.instance_config["capacity_rebalance"]

  # Cannot add a warm pool to Auto Scaling groups that have a mixed instances policy.
  dynamic "mixed_instances_policy" {
    for_each = var.asg_warm_pool["enabled"] ? [] : [1]

    content {
      launch_template {
        launch_template_specification {
          launch_template_id = aws_launch_template.worker.id
          version            = aws_launch_template.worker.latest_version
        }

        dynamic "override" {
          for_each = var.instance_config["ec2_type"]

          content {
            instance_type = override.value
          }
        }
      }

      instances_distribution {
        on_demand_base_capacity                  = var.instance_config["on_demand_base_capacity"]
        on_demand_percentage_above_base_capacity = var.instance_config["on_demand_percentage_above_base_capacity"]
        spot_allocation_strategy                 = var.instance_config["spot_allocation_strategy"]
        spot_instance_pools                      = var.instance_config["spot_instance_pools"]
        spot_max_price                           = var.instance_spot_max_price
      }
    }
  }

  dynamic "tag" {
    for_each = merge(
      var.extra_tags,
      var.extra_asg_tags,
      {
        "Name"                              = "${var.name}-worker-${var.instance_config["name"]}"
        "Role"                              = "k8s-worker"
        "kubernetes.io/cluster/${var.name}" = "owned"
      },
      (var.enable_autoscaler != "true") ? {} : { "k8s.io/cluster-autoscaler/enabled" = "true" },
      (var.enable_node_termination_handler != "true") ? {} : { "aws-node-termination-handler/managed" = "true" },
      (var.instance_spot_max_price == "") ? {} : { "spot-max-price" = var.instance_spot_max_price }
    )

    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }

  lifecycle {
    ignore_changes = [
      load_balancers,
      target_group_arns,
      desired_capacity
    ]
  }
}

resource "aws_launch_template" "worker" {
  instance_type = var.instance_config["ec2_type"][0]
  image_id      = var.instance_config["image_id"]
  name_prefix   = "${var.name}-worker-${var.instance_config["name"]}-"

  vpc_security_group_ids = local.vpc_security_group_ids

  iam_instance_profile {
    arn = aws_iam_instance_profile.worker.arn
  }

  key_name  = var.debug_mode ? var.ssh_key : ""
  user_data = base64encode(data.ignition_config.s3.rendered)

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_type = var.instance_config["root_volume_type"]
      volume_size = var.instance_config["root_volume_size"]
      iops        = lookup(local.iops_by_type.root, var.instance_config["root_volume_type"], null)
      throughput  = lookup(local.throughput_by_type.root, var.instance_config["root_volume_type"], null)
    }
  }

  lifecycle {
    create_before_destroy = true
  }
}

module "lifecycle_hook" {
  count  = var.enable_asg_life_cycle ? 1 : 0
  source = "github.com/getamis/terraform-aws-asg-lifecycle//modules/kubernetes?ref=v1.31.1.0"

  name                           = "${var.name}-worker-${var.instance_config["name"]}"
  cluster_name                   = var.name
  autoscaling_group_name         = aws_autoscaling_group.worker.name
  kubeconfig_s3_bucket           = var.s3_bucket
  kubeconfig_s3_object           = var.s3_object
  kubernetes_node_role           = var.instance_config["name"]
  lambda_function_vpc_subnet_ids = var.subnet_ids

  extra_tags = merge(
    {
      "Name"                              = "${var.name}-worker-${var.instance_config["name"]}"
      "kubernetes.io/cluster/${var.name}" = "owned"
    },
    var.extra_tags,
  )
}

