# IAM role for Lambda
resource "aws_iam_role" "lambda_check_iam" {
  name               = local.lambda_check_iam_role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role_lambda.json
}

# IAM policy attachment for Lambda to have full S3 access
resource "aws_iam_role_policy_attachment" "lambda_check_s3_full_access" {
  role       = aws_iam_role.lambda_check_iam.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# IAM policy attachment for Lambda to have full SQS access
resource "aws_iam_role_policy_attachment" "lambda_check_sqs_full_access" {
  role       = aws_iam_role.lambda_check_iam.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSQSFullAccess"
}

# Cloudwatch log group for Lambda
resource "aws_cloudwatch_log_group" "lambda_check" {
  name              = "/aws/lambda/${local.lambda_check_function_name}"
  retention_in_days = 7
}

# IAM policy for Lambda logging
resource "aws_iam_policy" "lambda_check_logging" {
  name        = "python_lambda_check_logging"
  path        = "/"
  description = "IAM policy for logging from a lambda"
  policy      = data.aws_iam_policy_document.lambda_logging.json
}

# IAM policy attachment for Lambda to log to CloudWatch
resource "aws_iam_role_policy_attachment" "lambda_check_logging" {
  role       = aws_iam_role.lambda_check_iam.name
  policy_arn = aws_iam_policy.lambda_check_logging.arn
}

# Lambda function
resource "aws_lambda_function" "check" {
  filename      = local.lambda_check_function_zip_file_path
  function_name = local.lambda_check_function_name

  role    = aws_iam_role.lambda_check_iam.arn
  handler = "lambda_function.lambda_handler"

  source_code_hash = data.archive_file.lambda_check.output_base64sha256

  runtime = "python3.10"
  timeout = 10

  layers = [
    "arn:aws:lambda:${var.AWS_REGION}:901920570463:layer:aws-otel-python-amd64-ver-1-24-0:1"
  ]

  environment {
    variables = {
      AWS_LAMBDA_EXEC_WRAPPER             = "/opt/otel-instrument"
      OPENTELEMETRY_COLLECTOR_CONFIG_FILE = "/var/task/otel/collector.yaml"
      NEWRELIC_OTLP_ENDPOINT              = substr(var.NEWRELIC_LICENSE_KEY, 0, 2) == "eu" ? "otlp.eu01.nr-data.net:4317" : "otlp.nr-data.net:4317"
      NEWRELIC_LICENSE_KEY                = var.NEWRELIC_LICENSE_KEY
      OUTPUT_S3_BUCKET_NAME               = aws_s3_bucket.output.id
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_check_logging,
    aws_cloudwatch_log_group.lambda_check,
  ]
}

# Lambda trigger for SQS
resource "aws_lambda_event_source_mapping" "sqs_trigger_for_lambda" {
  event_source_arn = aws_sqs_queue.queue.arn
  function_name    = aws_lambda_function.check.arn
}

resource "aws_security_group" "self" {
  description = "${local.name} self-group access"
  vpc_id      = var.network_vpc_id

  ingress {
    self      = true
    from_port = 0
    to_port   = 0
    protocol  = -1
  }
}

locals {
  admin_password = var.admin_password != "" ? var.admin_password : random_password.admin_password.result
  ami_name       = var.license_type == "PAYG" ? "F5 BIGIP-16.1.0-0.0.19 PAYG-Best 1Gbps*" : "F5 BIGIP-16.1.0-0.0.19 BYOL-All Modules 2Boot*"
  ami_name_v16   = var.license_type == "PAYG" ? "F5 BIGIP-16.0.1.1-0.0.6 PAYG-Best 1Gbps*" : "F5 BIGIP-16.0.1.1-0.0.6 BYOL-All Modules 2Boot*"
}

/*
* BIG-IP Username and Password
*/

resource "random_password" "admin_password" {
  length  = 16
  special = false
}

resource "random_string" "secret_prefix" {
  length  = 5
  special = false
}

resource "aws_secretsmanager_secret" "bigip_username" {
  name = "${random_string.secret_prefix.result}-bigip_username"
}

resource "aws_secretsmanager_secret_version" "bigip_username" {
  secret_id     = aws_secretsmanager_secret.bigip_username.id
  secret_string = var.admin_username
}

resource "aws_secretsmanager_secret" "bigip_password" {
  name = "${random_string.secret_prefix.result}-bigip_password"
}

resource "aws_secretsmanager_secret_version" "bigip_password" {
  secret_id     = aws_secretsmanager_secret.bigip_password.id
  secret_string = local.admin_password
}

/*
* BIG-IP Launch Template and Autoscale group
*/

data "template_file" "user_data" {
  template = file("${path.module}/templates/user_data.tpl")

  vars = {
    admin_password_secret          = aws_secretsmanager_secret.bigip_password.id
    bigiq_username_secret_location = var.bigiq_username_secret_location
    bigiq_password_secret_location = var.bigiq_password_secret_location
    bigiq_server                   = var.bigiq_server
    license_pool                   = var.bigiq_license_pool_name
    license_type                   = var.license_type
  }
}

data "aws_ami" "latest_f5_image" {
  most_recent = true
  owners      = ["679593333241"]

  filter {
    name   = "name"
    values = [local.ami_name]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_ami" "latest_f5_v16_image" {
  most_recent = true
  owners      = ["679593333241"]

  filter {
    name   = "name"
    values = [local.ami_name_v16]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_security_group" "bigip_1arm" {
  name        = "${var.name_prefix}-bigip-1arm-sg"
  description = "Allow inbound mgmt and https traffic"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 8443
    to_port     = 8443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_template" "bigip_1arm" {
  name          = "${var.name_prefix}-bigip-1arm-template"
  image_id      = data.aws_ami.latest_f5_image.id
  key_name      = var.key_pair
  instance_type = var.instance_type
  user_data     = base64encode(data.template_file.user_data.rendered)
  tags          = var.default_tags

  network_interfaces {
    subnet_id             = var.external_subnet_id
    security_groups       = [aws_security_group.bigip_1arm.id]
    delete_on_termination = true
    description           = "external"
    device_index          = 0
  }

  iam_instance_profile {
    name = aws_iam_instance_profile.bigip_1arm.name
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(tomap({ "Name" = "F5_LTM" }), var.default_tags)
  }
}

# Additional v16 launch template to demonstrate instance refresh

resource "aws_launch_template" "bigip_1arm_v16" {
  name          = "${var.name_prefix}-bigip-1arm-v16-template"
  image_id      = data.aws_ami.latest_f5_v16_image.id
  key_name      = var.key_pair
  instance_type = var.instance_type
  user_data     = base64encode(data.template_file.user_data.rendered)
  tags          = var.default_tags

  network_interfaces {
    subnet_id             = var.external_subnet_id
    security_groups       = [aws_security_group.bigip_1arm.id]
    delete_on_termination = true
    description           = "external"
    device_index          = 0
  }

  iam_instance_profile {
    name = aws_iam_instance_profile.bigip_1arm.name
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(tomap({ "Name" = "F5_LTM" }), var.default_tags)
  }
}

resource "aws_iam_instance_profile" "bigip_1arm" {
  name = "bigip_1arm"
  role = aws_iam_role.bigip_1arm_lt.name
}

data "aws_secretsmanager_secret_version" "bigiq_username" {
  count     = var.license_type == "PAYG" ? 0 : 1
  secret_id = var.bigiq_username_secret_location
}

data "aws_secretsmanager_secret_version" "bigiq_password" {
  count     = var.license_type == "PAYG" ? 0 : 1
  secret_id = var.bigiq_password_secret_location
}

resource "aws_iam_role" "bigip_1arm_lt" {
  name        = "${var.name_prefix}-bigip-1arm-lt"
  description = "AWS role assigned to BIG-IP devices"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "${var.name_prefix}-bigip-1arm-lt"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = ["secretsmanager:GetSecretValue"]
          Effect = "Allow"
          Resource = var.license_type == "PAYG" ? [
            aws_secretsmanager_secret.bigip_password.arn,
            ] : [
            aws_secretsmanager_secret.bigip_password.arn,
            data.aws_secretsmanager_secret_version.bigiq_username[0].arn,
            data.aws_secretsmanager_secret_version.bigiq_password[0].arn
          ]
        },
        {
          Action = [
            "ec2:DescribeInstances",
            "ec2:DescribeInstanceStatus",
            "ec2:DescribeAddresses",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DescribeNetworkInterfaceAttribute",
            "ec2:DescribeRouteTables"
          ]
          Effect   = "Allow"
          Resource = ["*"]
        }
      ]
    })
  }
}

resource "aws_autoscaling_group" "bigip_1arm" {
  name                      = "${var.name_prefix}-bigip-1arm-asg"
  vpc_zone_identifier       = [var.external_subnet_id]
  desired_capacity          = var.desired_capacity
  max_size                  = var.max_size
  min_size                  = var.min_size
  health_check_grace_period = 600
  health_check_type         = "EC2"
  target_group_arns         = module.nlb.target_group_arns

  instance_refresh {
    strategy = "Rolling"
    preferences {
      min_healthy_percentage = 50
    }
  }

  launch_template {
    id      = aws_launch_template.bigip_1arm.id
    version = "$Latest"
  }

  initial_lifecycle_hook {
    name                    = "${var.name_prefix}-bigip-1arm-launch"
    default_result          = "ABANDON"
    heartbeat_timeout       = 840
    lifecycle_transition    = "autoscaling:EC2_INSTANCE_LAUNCHING"
    notification_target_arn = aws_sns_topic.bigip_1arm.arn
    role_arn                = aws_iam_role.bigip_1arm_lh.arn
  }

  initial_lifecycle_hook {
    name                    = "${var.name_prefix}-bigip-1arm-terminate"
    default_result          = "CONTINUE"
    heartbeat_timeout       = 60
    lifecycle_transition    = "autoscaling:EC2_INSTANCE_TERMINATING"
    notification_target_arn = aws_sns_topic.bigip_1arm.arn
    role_arn                = aws_iam_role.bigip_1arm_lh.arn
  }

  warm_pool {
    pool_state                  = "Stopped"
    min_size                    = var.warm_pool_min_size
    max_group_prepared_capacity = var.warm_pool_max_prepared_capacity
  }
}

/*
* Autoscale Lifecycle hook
*/

resource "aws_sns_topic" "bigip_1arm" {
  name = "${var.name_prefix}-bigip-1arm"
}

resource "aws_sns_topic_subscription" "bigip_1arm" {
  topic_arn = aws_sns_topic.bigip_1arm.arn
  protocol  = "lambda"
  endpoint  = module.lifecycle_hook_lambda_function.lambda_function_arn
}

resource "aws_lambda_permission" "bigip_1arm" {
  statement_id  = "AllowExecutionFromSNS"
  action        = "lambda:InvokeFunction"
  function_name = module.lifecycle_hook_lambda_function.lambda_function_name
  principal     = "sns.amazonaws.com"
  source_arn    = aws_sns_topic.bigip_1arm.arn
}

resource "aws_iam_role" "bigip_1arm_lh" {
  name        = "${var.name_prefix}-bigip-1arm-lh"
  description = "IAM Role for autoscaling to call SNS for BIG-IP autoscale lifecycle hook"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "autoscaling.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "${var.name_prefix}-bigip-1arm-lh"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = ["sns:Publish"]
          Effect = "Allow"
          Resource = [
            aws_sns_topic.bigip_1arm.arn
          ]
        }
      ]
    })
  }
}

module "lifecycle_hook_lambda_function" {
  source = "terraform-aws-modules/lambda/aws"

  function_name = "bigip-1arm-lifecycle-function"
  description   = "Lifecycle hook lambda function for BIG-IP 1arm configuration."
  handler       = "app.lambda_handler"
  runtime       = "python3.8"
  source_path   = "${path.module}/lifecycle-hook"
  create_role   = false
  lambda_role   = aws_iam_role.bigip_1arm_lf.arn
  timeout       = 900
  tags          = var.default_tags

  environment_variables = {
    USER_SECRET_LOCATION       = aws_secretsmanager_secret.bigip_username.id
    PASS_SECRET_LOCATION       = aws_secretsmanager_secret.bigip_password.id
    AS3_BUCKET_NAME            = aws_s3_bucket.bigip_1arm_as3.id
    LICENSE_TYPE               = var.license_type
    BIGIQ_LICENSE_POOL_NAME    = var.bigiq_license_pool_name
    BIGIQ_SERVER               = var.bigiq_server
    BIGIQ_USER_SECRET_LOCATION = var.bigiq_username_secret_location
    BIGIQ_PASS_SECRET_LOCATION = var.bigiq_password_secret_location
  }
}

resource "aws_iam_role" "bigip_1arm_lf" {
  name        = "${var.name_prefix}-bigip-1arm-lf"
  description = "IAM Role for Lambda to call required resources for BIG-IP autoscale lifecycle hook lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "${var.name_prefix}-bigip-1arm-lf"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action   = ["ec2:DescribeInstances"]
          Effect   = "Allow"
          Resource = ["*"]
        },
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect   = "Allow"
          Resource = ["*"]
        },
        {
          Action = ["secretsmanager:GetSecretValue"]
          Effect = "Allow"
          Resource = var.license_type == "PAYG" ? [
            aws_secretsmanager_secret.bigip_username.arn,
            aws_secretsmanager_secret.bigip_password.arn,
            ] : [
            aws_secretsmanager_secret.bigip_username.arn,
            aws_secretsmanager_secret.bigip_password.arn,
            data.aws_secretsmanager_secret_version.bigiq_username[0].arn,
            data.aws_secretsmanager_secret_version.bigiq_password[0].arn
          ]
        },
        {
          Action   = ["s3:ListBucket"]
          Effect   = "Allow"
          Resource = [aws_s3_bucket.bigip_1arm_as3.arn]
        },
        {
          Action   = ["s3:GetObject"]
          Effect   = "Allow"
          Resource = ["${aws_s3_bucket.bigip_1arm_as3.arn}/*"]
        },
        {
          Action   = ["autoscaling:CompleteLifecycleAction"]
          Effect   = "Allow"
          Resource = ["*"]
        }
      ]
    })
  }
}

/*
* NLB
*/

module "nlb" {
  source  = "terraform-aws-modules/alb/aws"
  version = "~> 5.0"

  name               = "${var.name_prefix}-external-nlb"
  load_balancer_type = "network"
  vpc_id             = var.vpc_id
  subnets            = [var.external_subnet_id]

  http_tcp_listeners = [
    {
      port               = 443
      protocol           = "TCP"
      target_group_index = 0
    },
    {
      port               = 80
      protocol           = "TCP"
      target_group_index = 1
    }
  ]

  target_groups = [
    {
      backend_protocol = "TCP"
      backend_port     = 443
      target_type      = "instance"
    },
    {
      backend_protocol = "TCP"
      backend_port     = 80
      target_type      = "instance"
    },
  ]

  lb_tags = var.default_tags
}

/*
* AS3 S3 Bucket
*/

resource "random_string" "bucket_prefix" {
  length  = 5
  special = false
  upper   = false
}

resource "aws_s3_bucket" "bigip_1arm_as3" {
  bucket = "${var.name_prefix}-${random_string.bucket_prefix.result}-bigip-1arm-as3"
  acl    = "private"
  tags   = var.default_tags
}

resource "aws_s3_bucket_object" "bigip_1arm_as3" {
  for_each = fileset("${path.module}/as3", "**/*.json")

  bucket = aws_s3_bucket.bigip_1arm_as3.bucket
  key    = "as3-declarations/${each.value}"
  source = "${path.module}/as3/${each.value}"
}

# Data:     Get all AZ in defined region
data "aws_availability_zones" "available" {}

# Resource: VPC 
module "vpc" {
  source = "terraform-aws-modules/vpc/aws"
  name   = "${var.namespace}-vpc"
  cidr   = "10.0.0.0/16"

  azs        = data.aws_availability_zones.available.names
  create_igw = true

  public_subnets      = ["10.0.101.0/24"]
  database_subnets    = ["10.0.21.0/24", "10.0.22.0/24"]
  elasticache_subnets = ["10.0.31.0/24", "10.0.32.0/24"]

  enable_nat_gateway  = true
  single_nat_gateway  = true
  reuse_nat_ips       = true
  external_nat_ip_ids = aws_eip.nat.*.id

  create_database_subnet_group    = true
  create_elasticache_subnet_group = true
}


# Resource: Elastic IP
resource "aws_eip" "nat" {
  count = 1
  vpc   = true
}


# Resource: Security Group 
resource "aws_security_group" "public_sg" {
  name        = "${var.namespace}-public-sg"
  description = "Allow SSH and Web Server connection"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "SSH from the internet"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "WebServer from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.namespace}-allow_ssh_web"
  }
}

# Resource: Security Group 
resource "aws_security_group" "private_sg" {
  name        = "${var.namespace}-private-sg"
  description = "Allow Postgres and Redis connection inside VPC"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Postgres inside VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = tolist([module.vpc.vpc_cidr_block])
  }

  ingress {
    description = "Redis inside VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = tolist([module.vpc.vpc_cidr_block])
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "${var.namespace}-allow_postgres_redis"
  }
}

